'use strict';
window.BD_SCRIPTURE={"tel-dan": {"reference": "2 Samuel 7:16", "text": "Your house and kingdom will endure before me forever, and your throne will be established forever.", "excerpt": false, "context": "God’s promise to David is the background to the royal family named on the stone.", "source": "https://csbible.com/wp-content/uploads/2018/03/CSB_Pew_Bible_2nd_Printing.pdf"}, "nimrud": {"reference": "2 Kings 9:3", "text": "I anoint you king over Israel.", "excerpt": true, "context": "Elisha sends a messenger to anoint Jehu. Read chapters 9–10 for the change of dynasty.", "source": "https://csbible.com/wp-content/uploads/2018/03/CSB_Pew_Bible_2nd_Printing.pdf"}, "babylon": {"reference": "Ezra 1:2", "text": "This is what King Cyrus of Persia says: “The LORD, the God of the heavens, has given me all the kingdoms of the earth and has appointed me to build him a house at Jerusalem in Judah.”", "excerpt": false, "context": "Ezra recounts Cyrus’s permission to rebuild. Compare Isaiah 44:28–45:1.", "source": "https://csbible.com/wp-content/uploads/2018/03/CSB_Pew_Bible_2nd_Printing.pdf"}, "thebes": {"reference": "Judges 2:7", "text": "The people worshiped the LORD throughout Joshua’s lifetime and during the lifetimes of the elders who outlived Joshua. They had seen all the LORD’s great works he had done for Israel.", "excerpt": false, "context": "Judges looks back to the generation that entered the land. The stele supplies a separate dated mention of Israel.", "source": "https://csbible.com/wp-content/uploads/2018/03/CSB_Pew_Bible_2nd_Printing.pdf"}, "qumran": {"reference": "Isaiah 53:5–6", "text": "But he was pierced because of our rebellion, crushed because of our iniquities; punishment for our peace was on him, and we are healed by his wounds. We all went astray like sheep; we all have turned to our own way; and the LORD has punished him for the iniquity of us all.", "excerpt": false, "context": "Read the whole servant passage, Isaiah 52:13–53:12. Acts 8:26–35 shows Philip explaining it in relation to Jesus.", "source": "https://csbible.com/wp-content/uploads/2018/03/CSB_Pew_Bible_2nd_Printing.pdf"}, "avaris": {"reference": "Genesis 47:6", "text": "the land of Egypt is open before you; settle your father and brothers in the best part of the land. They can live in the land of Goshen. If you know of any capable men among them, put them in charge of my livestock.", "excerpt": false, "context": "Pharaoh addresses Joseph about his family. The pottery and buildings illuminate this cultural setting.", "source": "https://csbible.com/wp-content/uploads/2018/03/CSB_Pew_Bible_2nd_Printing.pdf"}, "galilee": {"reference": "Mark 4:38", "text": "He was in the stern, sleeping on the cushion. So they woke him up and said to him, “Teacher! Don’t you care that we’re going to die?”", "excerpt": false, "context": "Jesus and the disciples are crossing the lake. Read verses 35–41 for the storm and his response.", "source": "https://csbible.com/wp-content/uploads/2018/03/CSB_Pew_Bible_2nd_Printing.pdf"}, "bethesda": {"reference": "John 5:2", "text": "By the Sheep Gate in Jerusalem there is a pool, called Bethesda in Aramaic, which has five colonnades.", "excerpt": false, "context": "A colonnade is a covered walkway with columns. Read verses 1–15 for the man Jesus healed.", "source": "https://csbible.com/wp-content/uploads/2018/03/CSB_Pew_Bible_2nd_Printing.pdf"}, "caesarea": {"reference": "Luke 3:1", "text": "Pontius Pilate was governor of Judea", "excerpt": true, "context": "Luke names several rulers to locate John the Baptist’s ministry in history. John 18–19 narrates Jesus before Pilate.", "source": "https://csbible.com/wp-content/uploads/2018/03/CSB_Pew_Bible_2nd_Printing.pdf"}, "delphi": {"reference": "Acts 18:12", "text": "While Gallio was proconsul of Achaia", "excerpt": true, "context": "Acts describes a particular dispute in Corinth involving Paul and local accusers. Jesus, Paul and the first disciples were Jewish; this is not a claim against the Jewish people as a whole.", "source": "https://csbible.com/wp-content/uploads/2018/03/CSB_Pew_Bible_2nd_Printing.pdf"}, "oxyrhynchus": {"reference": "Luke 1:3–4", "text": "It also seemed good to me, since I have carefully investigated everything from the very first, to write to you in an orderly sequence, most honorable Theophilus, so that you may know the certainty of the things about which you have been instructed.", "excerpt": false, "context": "Luke explains why he writes. Surviving manuscript witnesses let readers compare how a written account was transmitted.", "source": "https://csbible.com/wp-content/uploads/2018/03/CSB_Pew_Bible_2nd_Printing.pdf"}, "megiddo": {"reference": "John 20:28", "text": "Thomas responded to him, “My Lord and my God!”", "excerpt": false, "context": "Thomas addresses the risen Jesus. Compare Philippians 2:5–11 with the community’s dedication on the floor.", "source": "https://csbible.com/wp-content/uploads/2018/03/CSB_Pew_Bible_2nd_Printing.pdf"}, "psalm": {"reference": "Psalm 100:4–5", "text": "Enter his gates with thanksgiving and his courts with praise. Give thanks to him and bless his name. For the LORD is good, and his faithful love endures forever; his faithfulness, through all generations.", "excerpt": false, "context": "A psalm of thanksgiving for the Table Room.", "source": "https://csbible.com/wp-content/uploads/2018/03/CSB_Pew_Bible_2nd_Printing.pdf"}, "ending": {"reference": "John 11:25–26", "text": "Jesus said to her, “I am the resurrection and the life. The one who believes in me, even if he dies, will live. Everyone who lives and believes in me will never die. Do you believe this?”", "excerpt": false, "context": "Jesus speaks to Martha before raising Lazarus. Read John 11 in context.", "source": "https://csbible.com/wp-content/uploads/2018/03/CSB_Pew_Bible_2nd_Printing.pdf"}};
window.BD_SCRIPTURE_CREDIT='Scripture quotations marked CSB have been taken from the Christian Standard Bible®, Copyright © 2017 by Holman Bible Publishers. Used by permission. Christian Standard Bible® and CSB® are federally registered trademarks of Holman Bible Publishers.';
